void tst_QCborStreamReader::numbers()
{
    QFETCH_GLOBAL(bool, useDevice);
    QFETCH(QByteArray, data);
    QFETCH(QCborStreamReader::Type, type);
    QFETCH(double, expected);

    QBuffer buffer(&data);
    QCborStreamReader reader(useDevice ? QByteArray() : data);
    if (useDevice) {
        buffer.open(QIODevice::ReadOnly);
        reader.setDevice(&buffer);
    }
    QVERIFY(reader.isValid());
    QCOMPARE(reader.lastError(), QCborError::NoError);
    QCOMPARE(reader.type(), type);
    QVERIFY(reader.isNumber());

    const double actual = reader.toNumber();
    if (qIsNaN(expected)) {
        QVERIFY(qIsNaN(actual));
    } else {
        // exact comparison: no fuzziness is acceptable in the conversion
        QCOMPARE_EQ(actual, expected);
        QCOMPARE(std::signbit(actual), std::signbit(expected));
    }

    // check consistency with the type-specific getters
    switch (type) {
    case QCborStreamReader::Float16:
        if (!qIsNaN(actual))
            QCOMPARE_EQ(actual, double(reader.toFloat16()));
        break;
    case QCborStreamReader::Float:
        if (!qIsNaN(actual))
            QCOMPARE_EQ(actual, double(reader.toFloat()));
        break;
    case QCborStreamReader::Double:
        if (!qIsNaN(actual))
            QCOMPARE_EQ(actual, reader.toDouble());
        break;
    default:
        QVERIFY(reader.isInteger());
        break;
    }

    QVERIFY(reader.next());
    QVERIFY(!reader.hasNext());
    QVERIFY(!reader.isNumber());
}

void tst_QCborStreamReader::nonNumbers_data()
{
    QTest::addColumn<QByteArray>("data");
    QTest::addColumn<QCborStreamReader::Type>("type");

    QTest::newRow("false") << QByteArray("\\xf4") << QCborStreamReader::SimpleType;
    QTest::newRow("true") << QByteArray("\\xf5") << QCborStreamReader::SimpleType;
    QTest::newRow("null") << QByteArray("\\xf6") << QCborStreamReader::SimpleType;
    QTest::newRow("undefined") << QByteArray("\\xf7") << QCborStreamReader::SimpleType;
    QTest::newRow("simpletype-32") << QByteArray("\\xf8\\x20") << QCborStreamReader::SimpleType;
    QTest::newRow("bytearray") << QByteArray("\\x41\\x31") << QCborStreamReader::ByteArray;
    QTest::newRow("string") << QByteArray("\\x61\\x31") << QCborStreamReader::String;
    QTest::newRow("array") << QByteArray("\\x81\\x01") << QCborStreamReader::Array;
    QTest::newRow("map") << QByteArray("\\xa1\\x01\\x01") << QCborStreamReader::Map;
    QTest::newRow("bignum") << QByteArray("\\xc2\\x41\\x01") << QCborStreamReader::Tag;
    QTest::newRow("decimal")
            << QByteArray("\\xc4\\x82\\x21\\x19\\x6a\\xb3") << QCborStreamReader::Tag;
}

